/**
 * The shared hostile-input corpus for gate C6.
 *
 * Every value here is something a caller can produce with valid code and bad
 * data, so R4 makes each one a *result*, not a throw. The set is deliberately
 * weighted toward values that break serialization and hashing rather than
 * values that break rendering: the first `./ops` adapter shipped an eager
 * `hashValue(input)` outside the harness guard, and `undefined`, a cycle and a
 * `Date` were exactly what exposed it.
 */

/** Values that cannot be canonicalized, and so break a naive input hash. */
function unhashable(): unknown[] {
  const cyclic: Record<string, unknown> = { title: "cycle" };
  cyclic.self = cyclic;

  const deep: Record<string, unknown> = {};
  let cursor = deep;
  for (let index = 0; index < 500; index += 1) {
    const next: Record<string, unknown> = {};
    cursor.child = next;
    cursor = next;
  }

  return [
    undefined,
    null,
    cyclic,
    deep,
    new Date(0),
    Number.NaN,
    Number.POSITIVE_INFINITY,
    10n,
    Symbol("hostile"),
    () => "not a document",
  ];
}

/** Values that are shaped wrongly for any document engine. */
function malformed(): unknown[] {
  return [
    {},
    [],
    "",
    "not a document",
    0,
    false,
    { pages: null },
    { pages: "many" },
    { pages: [{ children: null }] },
    { pages: [{ children: [{ type: "�" }] }] },
    { pages: Array.from({ length: 3 }, () => ({ children: [{ type: undefined }] })) },
    new Uint8Array([0, 1, 2, 3]),
    Buffer.from("%PDF-1.7 truncated"),
  ];
}

export const HOSTILE_INPUTS: readonly unknown[] = Object.freeze([...unhashable(), ...malformed()]);

/**
 * A one-line label for a hostile value, since many of them cannot be
 * `JSON.stringify`ed and a failure report has to name which one broke.
 */
export function describeInput(value: unknown): string {
  if (value === undefined) return "undefined";
  if (value === null) return "null";
  if (typeof value === "bigint") return `${String(value)}n`;
  if (typeof value === "symbol") return value.toString();
  if (typeof value === "function") return "function";
  if (typeof value === "number" && !Number.isFinite(value)) return String(value);
  if (value instanceof Date) return "Date";
  if (value instanceof Uint8Array) return `Uint8Array(${String(value.byteLength)})`;
  try {
    const text = JSON.stringify(value);
    if (text === undefined) return typeof value;
    return text.length > 60 ? `${text.slice(0, 57)}...` : text;
  } catch {
    return "cyclic object";
  }
}
